CREATE TABLE IF NOT EXISTS work_log_ai_polish_state (subject_id TEXT NOT NULL,log_id TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'DIRTY' CHECK(state IN ('DIRTY','POLISHING','POLISHED','FAILED','BUDGET_BLOCKED')),fact_digest TEXT NOT NULL DEFAULT '',applied_digest TEXT NOT NULL DEFAULT '',provider TEXT NOT NULL DEFAULT '',model TEXT NOT NULL DEFAULT '',prompt_version TEXT NOT NULL DEFAULT '',not_before_at INTEGER NOT NULL,request_version INTEGER,last_error_code TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(subject_id,log_id));
CREATE INDEX IF NOT EXISTS idx_wl_ai_state_due ON work_log_ai_polish_state(state,not_before_at,updated_at);
CREATE TABLE IF NOT EXISTS work_log_ai_cache (provider TEXT NOT NULL,model TEXT NOT NULL,prompt_version TEXT NOT NULL,fact_digest TEXT NOT NULL,result_json TEXT NOT NULL,input_bytes INTEGER NOT NULL,output_bytes INTEGER NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(provider,model,prompt_version,fact_digest));
CREATE TABLE IF NOT EXISTS work_log_ai_daily_usage (usage_date TEXT NOT NULL,subject_id TEXT NOT NULL,automatic_calls INTEGER NOT NULL DEFAULT 0,manual_calls INTEGER NOT NULL DEFAULT 0,total_calls INTEGER NOT NULL DEFAULT 0,input_bytes INTEGER NOT NULL DEFAULT 0,output_bytes INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL,PRIMARY KEY(usage_date,subject_id));
